<section class="settings-section" aria-label="Notification settings">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading…</span>
            </div>
        </div>
    }
    else if (_prefs is not null)
    {
        @if (_message is not null)
        {
            <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null" aria-label="Close"></button>
            </div>
