                <div class="text-truncate">@(_avatarUrl ?? "Not set")</div>
            </div>
        </div>

        <div class="mb-3">
            <label for="displayName" class="form-label">Display Name</label>
            <input id="displayName" type="text" class="form-control" @bind="_displayName" />
        </div>

