<section class="settings-section" aria-label="Appearance settings">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading…</span>
            </div>
        </div>
    }
    else
    {
        @if (_message is not null)
        {
            <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null" aria-label="Close"></button>
            </div>
        }

        <h3 class="mb-4">Appearance</h3>

        <!-- Theme -->
        <div class="mb-4">
            <h5>Theme</h5>
            @foreach (var theme in _themes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme.Key}")"
                           value="@theme.Key" checked="@(_theme == theme.Key)"
                           @onchange="() => _theme = theme.Key" />
                    <label class="form-check-label" for="@($"theme-{theme.Key}")">@theme.Label</label>
                </div>
            }
        </div>

        <!-- Font Size -->
        <div class="mb-4">
            <h5>Font Size</h5>
            @foreach (var size in _fontSizes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"font-{size.Key}")"
                           value="@size.Key" checked="@(_fontSize == size.Key)"
                           @onchange="() => _fontSize = size.Key" />
                    <label class="form-check-label" for="@($"font-{size.Key}")">@size.Label</label>
                </div>
            }
        </div>

        <!-- Language -->
        <div class="mb-4">
            <label for="language" class="form-label"><h5 class="d-inline">Language</h5></label>
            <select id="language" class="form-select" style="max-width: 280px;"
                    @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang.Key">@lang.Label</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                       checked="@_compactMode" @onchange="e => _compactMode = (bool)e.Value!" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="mb-4">
            <h5>Preview</h5>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
            }
            Save
        </button>
    }
</section>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    private record OptionItem(string Key, string Label);

    private static readonly OptionItem[] _themes =
    [
        new("Light", "Light"),
        new("Dark", "Dark"),
        new("System", "System")
    ];

    private static readonly OptionItem[] _fontSizes =
    [
        new("Small", "Small"),
        new("Medium", "Medium"),
        new("Large", "Large")
    ];

    private static readonly OptionItem[] _languages =
    [
        new("en", "English"),
        new("es", "Español"),
        new("fr", "Français"),
        new("de", "Deutsch"),
        new("ja", "日本語"),
        new("zh", "中文")
    ];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "System" => "preview-system",
            _ => "preview-light"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-small",
            "Large" => "preview-font-large",
            _ => "preview-font-medium"
        });

        if (_compactMode)
            classes.Add("preview-compact");

        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved.";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save settings: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

