toolArgs.file_text:
.preview-area {
    border: 1px solid var(--bs-border-color);
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.2s ease;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1a1a2e;
    color: #e0e0e0;
}

.preview-system {
    background: #f0f0f0;
    color: #333;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.25rem;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-body {
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.35rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.preview-compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-body {
    margin-bottom: 0.4rem;
}

.preview-dark .preview-button {
    border-color: #7c7cff;
    color: #7c7cff;
}

