arguments.file_text:
@page "/settings"
@using sv_fa1c0616c1124440927457c6d6c76a4c.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 70px);
    border: 1px solid var(--bs-border-color);
    border-radius: 0.5rem;
    overflow: hidden;
    margin: 1rem;
    background: var(--bs-body-bg);
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

::deep .settings-section {
    max-width: 680px;
}

